// Query database for human-approved orders ready for printing
// In production, this would use Supabase node
// For testing, we'll generate mock approved orders

const mockApprovedOrders = [
  {
    id: '123e4567-e89b-12d3-a456-426614174000',
    amazon_order_id: 'TEST-ORDER-001',
    status: 'book_assembly_completed',
    workflow_step: 'book_assembly',
    next_workflow: '4-print-fulfillment',
    human_approved: true,
    qa_score: 0.92,
    requires_human_review: false,

    // Customer info
    customer_email: 'jane.smith@example.com',
    customer_name: 'Jane Smith',
    shipping_address: {
      Name: 'Jane Smith',
      AddressLine1: '123 Main Street',
      City: 'Portland',
      StateOrRegion: 'OR',
      PostalCode: '97201',
      CountryCode: 'US'
    },

    // Book info
    final_book_url: 'https://r2.cloudflare.com/little-hero-assets/books/TEST-ORDER-001/final-book.pdf',
    final_cover_url: 'https://r2.cloudflare.com/little-hero-assets/books/TEST-ORDER-001/cover.png',

    // Character info
    character_specs: {
      childName: 'Emma',
      skinTone: 'medium',
      hairColor: 'brown',
      hairStyle: 'short/curly',
      age: '5',
      pronouns: 'she/her',
      favoriteColor: 'purple',
      animalGuide: 'unicorn',
      clothingStyle: 'dress'
    },

    // Timestamps
    book_assembly_completed_at: '2025-10-15T05:00:00.000Z',
    human_reviewed_at: '2025-10-15T05:15:00.000Z',
    human_reviewer: 'QA Team',

    // Print fields (empty for new orders)
    print_job_id: null,
    print_status: null,
    print_submission_started_at: null
  }
];

console.log(`✅ Found ${mockApprovedOrders.length} approved orders ready for printing`);
return mockApprovedOrders.map(order => ({ json: order }));

// Verify order is human-approved before processing
const orderData = $input.first().json;

// Critical check: Only process human-approved orders
if (!orderData.human_approved) {
  console.log(`❌ Order ${orderData.amazon_order_id} not human-approved, skipping`);
  return [];
}

// Check if already submitted to print
if (orderData.print_job_id) {
  console.log(`⚠️ Order ${orderData.amazon_order_id} already submitted to print, skipping`);
  return [];
}

// Verify status
if (orderData.status !== 'book_assembly_completed') {
  console.log(`❌ Order ${orderData.amazon_order_id} status is ${orderData.status}, not ready for print`);
  return [];
}

console.log(`✅ Order ${orderData.amazon_order_id} approved for printing`);
console.log(`   QA Score: ${orderData.qa_score}`);
console.log(`   Reviewed by: ${orderData.human_reviewer}`);

return [{ json: orderData }];

// Validate all print requirements before submission
const orderData = $input.first().json;
const shippingAddr = orderData.shipping_address || {};

// Validate print requirements
const printValidation = {
  hasFinalBook: !!orderData.final_book_url,
  hasCover: !!orderData.final_cover_url,
  hasShippingAddress: !!(shippingAddr.AddressLine1 && shippingAddr.City && shippingAddr.StateOrRegion && shippingAddr.PostalCode),
  hasCustomerInfo: !!(orderData.customer_name && orderData.customer_email),
  hasOrderId: !!orderData.amazon_order_id,
  bookSize: '8x10', // Fixed size for V1
  pageCount: 16, // Fixed page count (14 interior + covers)
  printQuality: 'standard' // Fixed quality for V1
};

const validationErrors = [];
if (!printValidation.hasFinalBook) validationErrors.push('Missing final book URL');
if (!printValidation.hasCover) validationErrors.push('Missing cover URL');
if (!printValidation.hasShippingAddress) validationErrors.push('Incomplete shipping address');
if (!printValidation.hasCustomerInfo) validationErrors.push('Missing customer information');
if (!printValidation.hasOrderId) validationErrors.push('Missing order ID');

const isValidForPrinting = validationErrors.length === 0;

if (!isValidForPrinting) {
  console.log(`❌ Print validation failed for order: ${orderData.amazon_order_id}`);
  console.log(`   Errors: ${validationErrors.join(', ')}`);
  return [];
}

console.log(`✅ Print validation passed for order: ${orderData.amazon_order_id}`);

const validatedOrder = {
  ...orderData,
  printValidation: printValidation,
  validationErrors: validationErrors,
  isValidForPrinting: isValidForPrinting,
  print_validated_at: new Date().toISOString()
};

return [{ json: validatedOrder }];

// Mock Lulu Print-on-Demand API submission
// In production, this would be an HTTP Request node to Lulu API
const orderData = $input.first().json;
const shippingAddr = orderData.shipping_address;

// Simulate Lulu API request body
const luluRequest = {
  line_items: [
    {
      external_id: orderData.amazon_order_id,
      printable_normalization: {
        cover: orderData.final_cover_url,
        interior: orderData.final_book_url
      },
      quantity: 1,
      pod_package_id: 'softcover-8x10-standard'
    }
  ],
  contact_email: orderData.customer_email,
  shipping_address: {
    name: shippingAddr.Name,
    street1: shippingAddr.AddressLine1,
    city: shippingAddr.City,
    state_code: shippingAddr.StateOrRegion,
    postcode: shippingAddr.PostalCode,
    country_code: shippingAddr.CountryCode
  }
};

console.log('📤 Submitting to Lulu (MOCK):', JSON.stringify(luluRequest, null, 2));

// Mock Lulu API response
const mockLuluResponse = {
  id: `LULU-${Date.now()}`,
  status: 'CREATED',
  line_items: [
    {
      id: `LULU-ITEM-${Date.now()}`,
      external_id: orderData.amazon_order_id,
      status: 'CREATED',
      tracking_number: null,
      tracking_url: null
    }
  ],
  shipping_address: luluRequest.shipping_address,
  created_at: new Date().toISOString(),
  estimated_ship_date: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3 days from now
  cost: {
    total: '12.45',
    currency: 'USD',
    line_item_costs: [
      {
        total: '8.95',
        total_excluding_tax: '8.95'
      }
    ],
    shipping_cost: {
      total: '3.50',
      total_excluding_tax: '3.50'
    }
  }
};

console.log(`✅ Mock Lulu response received: Job ID ${mockLuluResponse.id}`);

return [{ json: { ...orderData, luluResponse: mockLuluResponse } }];

// Process Lulu API response and extract print job details
const orderData = $input.first().json;
const luluResponse = orderData.luluResponse;

// Extract print job information from Lulu response
const printJobInfo = {
  printJobId: luluResponse.id,
  status: luluResponse.status,
  estimatedShipDate: luluResponse.estimated_ship_date,
  trackingNumber: luluResponse.line_items[0]?.tracking_number || null,
  trackingUrl: luluResponse.line_items[0]?.tracking_url || null,
  cost: parseFloat(luluResponse.cost.total),
  currency: luluResponse.cost.currency,
  createdAt: luluResponse.created_at
};

console.log(`✅ Print job submitted to Lulu: ${printJobInfo.printJobId}`);
console.log(`   Status: ${printJobInfo.status}`);
console.log(`   Cost: $${printJobInfo.cost}`);
console.log(`   Est. Ship: ${printJobInfo.estimatedShipDate}`);

const orderWithPrintJob = {
  ...orderData,
  print_job_id: printJobInfo.printJobId,
  print_status: printJobInfo.status,
  print_submission_started_at: printJobInfo.createdAt,
  fulfillment_cost: printJobInfo.cost,
  estimated_ship_date: printJobInfo.estimatedShipDate
};

return [{ json: orderWithPrintJob }];

